#!/usr/bin/env python3
"""Ad-hoc verification for /workspace/cis/greet.py."""
import subprocess, sys, os

FILE = "/workspace/cis/greet.py"
errors = []

# 1. File exists
if not os.path.isfile(FILE):
    errors.append(f"MISSING: {FILE}")

# 2. Syntax check
try:
    import py_compile
    py_compile.compile(FILE, doraise=True)
except py_compile.PyCompileError as e:
    errors.append(f"SYNTAX ERROR: {e}")

# 3. Execution
try:
    result = subprocess.run(["python3", FILE], capture_output=True, text=True, timeout=10)
    if result.returncode != 0:
        errors.append(f"EXIT CODE: {result.returncode}")
    lines = result.stdout.strip().split("\n")
    if len(lines) < 2:
        errors.append(f"EXPECTED 2+ output lines, got {len(lines)}: {lines}")
    else:
        if lines[0] != "Hello World":
            errors.append(f"LINE 1 mismatch: expected 'Hello World', got '{lines[0]}'")
        # Line 2 should be a parsable datetime
        import datetime
        try:
            datetime.datetime.strptime(lines[1], "%Y-%m-%d %H:%M:%S.%f")
        except ValueError:
            errors.append(f"LINE 2 not a valid timestamp: '{lines[1]}'")
except Exception as e:
    errors.append(f"EXECUTION ERROR: {e}")

# 4. Line count — no bloat
with open(FILE) as f:
    content = f.read()
    loc = [l for l in content.split("\n") if l.strip() and not l.strip().startswith("#")]
    if len(loc) > 4:
        errors.append(f"BLOAT: {len(loc)} non-comment lines (max 4)")

if errors:
    for e in errors:
        print(f"FAIL: {e}", file=sys.stderr)
    sys.exit(1)

print("VERIFIED: greet.py — exists, syntax-ok, correct output, minimal")

